-- =====================================================================
-- md_std_tat_others_fill.sql
-- เพิ่ม 84 ประเทศที่มี arrival ปี 2024 ลงใน OTHERS buckets ของ STD_TAT
-- Schema: Oracle TAT (139.180.208.163:1521 SID=XE schema=TAT)
-- รันทั้งไฟล์ครั้งเดียว (มี COMMIT ในตัว + BEFORE/AFTER verify)
--
-- เป้าหมาย: nation_compare 08-09-2024 STD_TAT 72,758 → 72,955 (= ALL_TAT)
--
-- โครงสร้าง STD_TAT มี 4 OTHERS regions ว่างเปล่าอยู่แล้ว:
--   NODE=125 'OTHERS IN EAST ASIA'                              (parent=111)
--   NODE=151 'OTHERS IN ASEAN, SOUTH ASIA, SOUTH PACIFIC'       (parent=111)
--   NODE=211 'OTHERS IN EUROPE'                                 (parent=152)
--   NODE=261 'OTHERS IN THE AMERICAS, THE MIDDLE EAST AND AFRICA' (parent=152)
--
-- NODE_ID range ใช้: 900-983 (max ปัจจุบัน = 861)
-- SORT_ORDER range: ต่อจาก parent (เริ่มที่ 16, 42, 102, 152 ของ STD_TAT structure)
-- GROUP_ID = 2 (STD_TAT)
-- =====================================================================

-- ====== BEFORE: ตรวจสถานะ OTHERS regions ของ STD_TAT (ต้องเห็น 4 row, NC=0 ทุกตัว) ======
SELECT 'BEFORE - STD_TAT OTHERS regions' AS phase, NODE_ID, NAME_EN,
       (SELECT COUNT(*) FROM MD_COUNTRY_GROUP_NODE c
        WHERE c.PARENT_NODE_ID = n.NODE_ID AND c.NODE_TYPE = 'COUNTRY') AS NC
FROM MD_COUNTRY_GROUP_NODE n
WHERE n.NODE_ID IN (125, 151, 211, 261)
ORDER BY n.NODE_ID;

-- ====== BACKUP (optional) ======
-- CREATE TABLE MD_COUNTRY_GROUP_NODE_BAK_STDTAT_OTHERS AS SELECT * FROM MD_COUNTRY_GROUP_NODE;

-- =====================================================================
-- INSERT: 84 country nodes ลง OTHERS buckets
-- format: (NODE_ID, GROUP_ID=2, PARENT, 'COUNTRY', NAME, NULL, COUNTRY_ID, SORT, 'N', 'N')
-- =====================================================================

-- ---------- OTHERS IN EAST ASIA (parent=125) — 2 ประเทศ ----------

-- ---------- OTHERS IN ASEAN, SOUTH ASIA, SOUTH PACIFIC (parent=151) — 16 ประเทศ ----------

-- ---------- OTHERS IN EUROPE (parent=211) — 4 ประเทศ ----------

-- ---------- OTHERS IN THE AMERICAS, THE MIDDLE EAST AND AFRICA (parent=261) — 62 ประเทศ ----------

COMMIT;

-- =====================================================================
-- AFTER: ตรวจสอบหลัง INSERT
-- =====================================================================

-- 1) นับ COUNTRY ใน 4 OTHERS bucket (ต้องได้: 2, 16, 4, 62)
SELECT 'AFTER - OTHERS country counts' AS phase, NODE_ID, NAME_EN,
       (SELECT COUNT(*) FROM MD_COUNTRY_GROUP_NODE c
        WHERE c.PARENT_NODE_ID = n.NODE_ID AND c.NODE_TYPE = 'COUNTRY') AS NC
FROM MD_COUNTRY_GROUP_NODE n
WHERE n.NODE_ID IN (125, 151, 211, 261)
ORDER BY n.NODE_ID;

-- 2) นับ country ทั้งหมดใน STD_TAT (ต้องได้ 121 + 84 = 205)
SELECT 'AFTER - STD_TAT total country count' AS phase, COUNT(DISTINCT n.COUNTRY_ID) AS CNT
FROM MD_COUNTRY_GROUP g
JOIN MD_COUNTRY_GROUP_NODE n ON n.GROUP_ID = g.GROUP_ID
WHERE g.GROUP_CODE = 'STD_TAT' AND n.NODE_TYPE = 'COUNTRY' AND n.COUNTRY_ID IS NOT NULL;

-- 3) ไม่มี duplicate COUNTRY_ID ใน STD_TAT (ต้องได้ 0 rows)
SELECT 'AFTER - STD_TAT duplicates' AS phase, n.COUNTRY_ID, COUNT(*) AS CNT
FROM MD_COUNTRY_GROUP g
JOIN MD_COUNTRY_GROUP_NODE n ON n.GROUP_ID = g.GROUP_ID
WHERE g.GROUP_CODE = 'STD_TAT' AND n.NODE_TYPE = 'COUNTRY' AND n.COUNTRY_ID IS NOT NULL
GROUP BY n.COUNTRY_ID
HAVING COUNT(*) > 1;
